   112	            settings: settings, range: range, codec: pump.webmCodec, picture: pump.picture,
   113	            preSkip: opus?.preSkip, chapters: chapters
   114	        ).json()
   115	    }
   116	
   117	    @available(*, unavailable) required init?(coder: NSCoder) {
   118	        fatalError("ExportWebMWriter does not support NSCoder")
   119	    }
   120	
   121	    /// A reader of `composition` over `range`, for one output.
   122	    private static func reader(_ composition: AVComposition, range: CMTimeRange) throws
   123	        -> AVAssetReader
   124	    {
   125	        do {
   126	            let reader = try AVAssetReader(asset: composition)
   127	            reader.timeRange = range
   128	            return reader
   129	        } catch {
   130	            throw Exporter.ExportError.failed(error.localizedDescription)
   131	        }
   132	    }
   133	
   134	    /// `ExportWriter.normalizeAudio`'s rule: a non-finite, non-positive or unit gain is
   135	    /// ignored, so an export that was not normalised reads the 16-bit decode.
   136	    func normalizeAudio(byLinearGain gain: Float) {
   137	        guard gain.isFinite, gain > 0, gain != 1 else { return }
