   139	    }
   140	
   141	    // MARK: - Running
   142	
   143	    /// Starts the write. Main thread; `completion` is called exactly once, on main.
   144	    func start(completion: @escaping (Result<URL, any Error>) -> Void) {
   145	        self.completion = completion
   146	        guard !isStopping else { return report(.failure(Exporter.ExportError.cancelled)) }
   147	        if let audioReader {
   148	            let output = ExportWriter.audioReadOutput(built, gained: audioGain != nil)
   149	            guard audioReader.canAdd(output) else {
   150	                return report(.failure(Exporter.ExportError.failed(
   151	                    "The audio mix could not be read for export.")))
   152	            }
   153	            audioReader.add(output)
   154	            audioOutput = output
   155	        }
   156	        let webm: ReelWebM
   157	        do {
   158	            webm = try ReelWebM(path: destination.path, layoutJSON: layoutJSON)
   159	        } catch {
