   161	            discard()
   162	            return report(.failure(Exporter.ExportError.failed(
   163	                "The WebM file could not be made: \(error.localizedDescription)")))
   164	        }
   165	        self.webm = webm
   166	        guard videoReader.startReading() else {
   167	            discard()
   168	            return report(.failure(videoReader.error ?? Exporter.ExportError.failed(
   169	                "The composition could not be read for export.")))
   170	        }
   171	        // A reader not yet started is started; the video one is (nothing reads either yet).
   172	        if let audioReader, audioReader.status == .unknown, !audioReader.startReading() {
   173	            videoReader.cancelReading()
   174	            discard()
   175	            return report(.failure(audioReader.error ?? Exporter.ExportError.failed(
   176	                "The audio mix could not be read for export.")))
   177	        }
