   180	            sink: ExportWebMPacketSink(webm: webm, fault: fault), output: videoOutput,
   181	            on: videoQueue, group: group, isStopping: { [weak self] in self?.isStopping ?? true },
   182	            readFailure: { [weak self] in self?.readFailure(of: self?.videoReader) },
   183	            fail: { [weak self] error in self?.stopped(with: error) },
   184	            advance: { [weak self] time in self?.advance(to: time) })
