   216	    // MARK: - The audio pump
   217	
   218	    /// Reads the mix to its end, encodes it and adds each packet, holding the newest back so
   219	    /// the last one can carry the tail's DiscardPadding (CX-15 (5)), or stops at the flag
   220	    /// before a read.
   221	    ///
   222	    /// **Times are the stamps'.** Each buffer is placed at its rebased stamp
   223	    /// (`ExportAudioEnd.align`: silence for a gap, the covered head cut), so the stream the
   224	    /// encoder is fed is the timeline's sound frame for frame from the range's start, and
   225	    /// packet k's first frame is the one stamped k × 960 / 48 kHz — k × 20 ms, a whole tick of
   226	    /// WebM's 1 ms timecode scale — which is the time it is added at.
   227	    private func pumpAudio(
   228	        _ output: AVAssetReaderOutput, into webm: ReelWebM, through opus: ExportOpusEncoder
   229	    ) {
   230	        let gain = audioGain
   231	        var held: Data?
   232	        var added: Int64 = 0
   233	        let packetNs = Int64(ExportOpusEncoder.framesPerPacket) * 1_000_000_000 / 48_000
   234	        let add = { (packet: Data, padding: Int64) throws in
   235	            try webm.add(
   236	                track: ReelWebM.audio, ptsNs: added * packetNs, key: true,
   237	                discardPaddingNs: padding, data: packet)
   238	            added += 1
   239	        }
   240	        let feed = { (packets: [Data]) throws in
   241	            for packet in packets {
   242	                if let previous = held { try add(previous, 0) }
   243	                held = packet
   244	            }
   245	        }
   246	        var reads = 0
   247	        do {
   248	            while true {
   249	                guard !isStopping else { return }
   250	                reads += 1
   251	                try fault?.beforeAudioRead(reads)
   252	                guard let decoded = output.copyNextSampleBuffer() else {
   253	                    if let error = readFailure(of: audioReader) {
   254	                        stopped(with: error)
   255	                        return
   256	                    }
   257	                    break
   258	                }
   259	                let time = CMSampleBufferGetPresentationTimeStamp(decoded) - range.start
   260	                guard time.isNumeric, time >= .zero else { continue }
   261	                if gain != nil, CMSampleBufferGetNumSamples(decoded) == 0 { continue }
   262	                guard let sample = gain == nil ? decoded : gain?.apply(to: decoded) else {
   263	                    stopped(with: Exporter.ExportError.failed(
   264	                        "The loudness gain could not be applied to a sample."))
   265	                    return
   266	                }
   267	                let frame = CMTimeConvertScale(
   268	                    time, timescale: CMTimeScale(ExportAudioEnd.sampleRate),
   269	                    method: .roundHalfAwayFromZero
   270	                ).value
   271	                for placed in audioEnd.align(sample, at: Int(frame)) {
   272	                    guard let fitted = audioEnd.fit(placed) else { continue }
   273	                    try feed(try opus.encode(fitted))
   274	                }
   275	            }
   276	            for silence in audioEnd.padding() {
   277	                try feed(try opus.encode(silence))
   278	            }
   279	            var tail = (held.map { [$0] } ?? []) + (try opus.finish())
   280	            // The decoded length is packets × 960 − pre-skip; the surplus over #337's
   281	            // target is cut whole packets first, then by the last one's DiscardPadding.
   282	            var padding = (Int(added) + tail.count) * ExportOpusEncoder.framesPerPacket
   283	                - opus.preSkip - audioEnd.target
   284	            while padding >= ExportOpusEncoder.framesPerPacket, !tail.isEmpty {
   285	                tail.removeLast()
   286	                padding -= ExportOpusEncoder.framesPerPacket
   287	            }
   288	            guard padding >= 0, padding < ExportOpusEncoder.framesPerPacket else {
   289	                stopped(with: Exporter.ExportError.failed(
   290	                    "The audio could not be encoded to its exact length."))
   291	                return
   292	            }
   293	            let paddingNs = (Int64(padding) * 1_000_000_000 + 24_000) / 48_000
   294	            for (index, packet) in tail.enumerated() {
   295	                try add(packet, index == tail.count - 1 ? paddingNs : 0)
   296	            }
   297	            try webm.endTrack(ReelWebM.audio)
   298	        } catch {
   299	            stopped(with: error)
   300	        }
   301	    }
