   309	    }
   310	
   311	    private func stopped(with error: any Error) {
   312	        lock.lock()
   313	        let first = failure == nil
   314	        if first { failure = error }
   315	        lock.unlock()
   316	        // The unified log (not stdout or the proofs' log), so a stop names its cause.
   317	        let which = first ? "first" : "later"
   318	        let why = error.localizedDescription
   319	        Self.log.error(
   320	            "WebM export stopped (\(which, privacy: .public)): \(why, privacy: .public)")
   321	    }
   322	
   323	    private static let log = Logger(subsystem: "com.kgalligan.FrameJob", category: "export.webm")
   324	
   325	    private func readFailure(of reader: AVAssetReader?) -> (any Error)? {
   326	        guard let reader, reader.status == .failed else { return nil }
   327	        return reader.error
   328	            ?? Exporter.ExportError.failed("The composition could not be read to the end.")
   329	    }
   330	
   331	    private func advance(to time: CMTime) {
   332	        guard totalSeconds > 0 else { return }
   333	        let fraction = CMTimeGetSeconds(time) / totalSeconds
   334	        lock.lock()
   335	        progressValue = min(max(fraction, progressValue), 1)
   336	        lock.unlock()
   337	    }
   338	
   339	    /// Main thread, once both pumps have left (each reader already cancelled by its own
   340	    /// pump on a stop): the encoder closed, then the file finished off main or dropped and
   341	    /// removed.
   342	    private func allPumpsLeft() {
   343	        lock.lock()
   344	        let error = failure
   345	        let cancelled = cancelRequested
   346	        lock.unlock()
   347	        if fault != nil {
   348	            let shared = audioReader === videoReader ? " (one reader)" : ""
   349	            ExportWebMDevFault.log(
   350	                "readers: video \(videoReader.status.rawValue), audio "
   351	                    + (audioReader.map { "\($0.status.rawValue)" } ?? "none") + shared)
   352	        }
   353	        pump.close()
   354	        if let error { return finishFailed(error) }
   355	        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
   356	        guard let webm else { return finishFailed(Exporter.ExportError.cancelled) }
   357	        videoQueue.async { [weak self] in
   358	            let closed: (any Error)?
   359	            do {
   360	                try webm.finish()
   361	                closed = nil
   362	            } catch {
   363	                closed = Exporter.ExportError.failed(
   364	                    "The WebM file could not be finished: \(error.localizedDescription)")
   365	            }
   366	            DispatchQueue.main.async { self?.fileClosed(closed) }
   367	        }
   368	    }
   369	
   370	    private func fileClosed(_ error: (any Error)?) {
   371	        lock.lock()
   372	        let cancelled = cancelRequested
   373	        lock.unlock()
   374	        if let error { return finishFailed(error) }
   375	        // A cancel while the file was being closed still means "I do not want this file".
   376	        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
   377	        lock.lock()
   378	        progressValue = 1
   379	        lock.unlock()
   380	        report(.success(destination))
   381	    }
   382	
   383	    private func finishFailed(_ error: any Error) {
   384	        discard()
   385	        report(.failure(error))
   386	    }
   387	
   388	    /// Drops the writer and removes the part-written file.
   389	    private func discard() {
   390	        webm = nil
   391	        try? FileManager.default.removeItem(at: destination)
   392	    }
   393	
   394	    /// The one exit, main thread, at most once.
   395	    private func report(_ result: Result<URL, any Error>) {
   396	        guard let completion else { return }
   397	        self.completion = nil
   398	        completion(result)
   399	    }
   400	}

