//! The block-level half of the WebM writer's EBML (spec §11 CX-15 (3)): the
//! Cues and the builders of a block's body and its BlockGroup, which
//! `webm_writer.rs` places in its Clusters.
//!
//! Moved whole out of `webm_ebml.rs` under the 400-line cap for a new module,
//! as codec-export C5's toll T2, a pure move. `webm_ebml.rs` re-exports the
//! builders and `CUES`, so every `ebml::` path in `webm_writer.rs` holds.

use crate::webm_ebml::{binary, int, master, uint, vint, BLOCK_GROUP};

const BLOCK: u32 = 0xA1;
const DISCARD_PADDING: u32 = 0x75A2;
pub(crate) const CUES: u32 = 0x1C53_BB6B;
const CUE_POINT: u32 = 0xBB;
const CUE_TIME: u32 = 0xB3;
const CUE_TRACK_POSITIONS: u32 = 0xB7;
const CUE_TRACK: u32 = 0xF7;
const CUE_CLUSTER_POSITION: u32 = 0xF1;

/// Cues of (time in ms, Cluster position in the Segment's data), track 1.
     1	import AVFoundation
     2	import os
     3	
     4	/// The WebM rows' pipeline (spec §11 CX-15, CX-16): `av1_webm` and `vp9_webm`, the composed
     5	/// movie read back exactly as `ExportWriter` reads it, its picture encoded by the same
     6	/// `ExportEncodePump` (SVT-AV1 or libvpx by `writer`) and its sound by `ExportOpusEncoder`,
     7	/// written into a WebM by the core (`ReelWebM`).
     8	///
     9	/// **A second `ExportPipeline`, and the exception to §7.8's one writer (CX-15 (2)).**
    10	/// `AVAssetWriter` writes no WebM, so this file is the WebM half of `ExportWriter` and
    11	/// nothing more: the same reader outputs (`ExportWriter.videoReadOutput` /
    12	/// `audioReadOutput`), each on a reader of its own (below), the same gain (`ExportAudioGain`), the same end of the sound
    13	/// (`ExportAudioEnd`, #337), the same chapters (`ExportChapter.partition`), the same size and
    14	/// rates (`encodedSize`, the pump). What is its own is the container: the core interleaves,
    15	/// clusters, cues and closes the file. **A composition with no audio track is a silent
    16	/// movie**, as in `ExportWriter.addAudio`: no audio output, encoder or queue, and the layout
    17	/// has no audio track.
    18	///
    19	/// **Two pumps.** The video pump is `ExportEncodePump` on `videoQueue` into an
    20	/// `ExportWebMPacketSink`. The audio pump reads, checks the time, applies the gain, cuts at
    21	/// the range (`end.fit`), encodes and adds, on `audioQueue`; once the read is dry it encodes
    22	/// the padding silence and the encoder's tail and cuts the surplus by DiscardPadding
    23	/// (CX-15 (5)). The sound is placed at its stamps (`ExportAudioEnd.align`), so a dropped
    24	/// straddling buffer or a hole in the stamps keeps later sound where it was. Neither waits
    25	/// on the file: the core queues what the interleave holds.
    26	///
    27	/// **One `AVAssetReader` per output (CX-15 (2), (6)).** Two outputs of ONE reader are
    28	/// coupled: an output nobody reads stalls the reader, so a pump that stopped could leave the
    29	/// other blocked in `copyNextSampleBuffer` for good, and `cancelReading()` cannot wake it —
    30	/// AVFoundation forbids it concurrently with a read, and it crashed (G-17). So the video
    31	/// composition output and the audio mix output each have their own reader over the same
    32	/// composition (measured: the same frames byte for byte and the same sound sample for
    33	/// sample, `webm_export_proof.py` R1), neither read waits on the other, and each pump, once it
    34	/// has left its loop on a stop, cancels its own reader on its own queue — no thread ever
    35	/// cancels another's (G-17's rule). A silent movie has the video reader alone.
    36	///
    37	/// **Cancellation, failure and progress** are `ExportWriter`'s: a flag both pumps read
    38	/// before each read, the first failure recorded once (`stopped(with:)`, logged), progress
    39	/// from the frames submitted. A cancelled or failed export drops the writer and removes the
    40	/// file; a finished one is closed by `ReelWebM.finish()` off the main thread and reported on
    41	/// main. `-RCDevWebMFault` (`ExportWebMDevFault`, dev tools only) puts a fault in either
    42	/// pump so a proof can time the stop.
    43	final class ExportWebMWriter: ExportPipeline, ExportAudioNormalizing {
    44	    private let built: BuiltComposition
    45	    private let destination: URL
    46	    private let range: CMTimeRange
    47	    private let totalSeconds: Double
