    55	    private let opus: ExportOpusEncoder?
    56	    private let audioEnd: ExportAudioEnd
    57	    private let layoutJSON: String
    58	    private var webm: ReelWebM?
    59	    /// Written once on main between `init` and `start`, then read only on `audioQueue`.
    60	    private var audioGain: ExportAudioGain?
    61	
    62	    private let videoQueue = DispatchQueue(
    63	        label: "com.kgalligan.framejob.export.webm.video", qos: .userInitiated)
    64	    private let audioQueue = DispatchQueue(
    65	        label: "com.kgalligan.framejob.export.webm.audio", qos: .userInitiated)
    66	
    67	    /// Guards everything the pumps and the main thread both touch.
