    93	        guard !built.composition.tracks(withMediaType: .video).isEmpty else {
    94	            throw Exporter.ExportError.emptyTimeline
    95	        }
    96	        let canvas = built.videoComposition.renderSize
    97	        videoOutput = ExportWriter.videoReadOutput(built, settings: settings)
