    99	            throw Exporter.ExportError.failed("The composition could not be read for export.")
   100	        }
   101	        videoReader.add(videoOutput)
   102	        pump = try ExportEncodePump(settings: settings, canvas: canvas, range: range)
   103	        // The silent movie (CX-15 (2)): no sound, no reader, encoder or audio track.
   104	        let hasAudio = !built.composition.tracks(withMediaType: .audio).isEmpty
   105	        audioReader = hasAudio ? try Self.reader(built.composition, range: range) : nil
   106	        opus = hasAudio
   107	            ? try ExportOpusEncoder(
   108	                bitRate: settings.audioBitrate.map { max(1, $0) }
   109	                    ?? ExportOpusEncoder.defaultBitRate)
