   112	            settings: settings, range: range, codec: pump.webmCodec, picture: pump.picture,
   113	            preSkip: opus?.preSkip, chapters: chapters
   114	        ).json()
   115	    }
   116	
   117	    @available(*, unavailable) required init?(coder: NSCoder) {
   118	        fatalError("ExportWebMWriter does not support NSCoder")
   119	    }
   120	
   121	    /// A reader of `composition` over `range`, for one output.
   122	    private static func reader(_ composition: AVComposition, range: CMTimeRange) throws
   123	        -> AVAssetReader
   124	    {
   125	        do {
   126	            let reader = try AVAssetReader(asset: composition)
