   128	            return reader
   129	        } catch {
   130	            throw Exporter.ExportError.failed(error.localizedDescription)
   131	        }
   132	    }
   133	
   134	    /// `ExportWriter.normalizeAudio`'s rule: a non-finite, non-positive or unit gain is
