   139	    }
   140	
   141	    // MARK: - Running
   142	
   143	    /// Starts the write. Main thread; `completion` is called exactly once, on main.
   144	    func start(completion: @escaping (Result<URL, any Error>) -> Void) {
   145	        self.completion = completion
   146	        guard !isStopping else { return report(.failure(Exporter.ExportError.cancelled)) }
