   177	        }
   178	        let group = DispatchGroup()
   179	        pump.run(
   180	            sink: ExportWebMPacketSink(webm: webm, fault: fault), output: videoOutput,
   181	            on: videoQueue, group: group, isStopping: { [weak self] in self?.isStopping ?? true },
   182	            readFailure: { [weak self] in self?.readFailure(of: self?.videoReader) },
   183	            fail: { [weak self] error in self?.stopped(with: error) },
   184	            advance: { [weak self] time in self?.advance(to: time) })
   185	        // The video reader's own cancel, on its queue after the pump's read loop (G-17).
   186	        group.enter()
   187	        videoQueue.async { [self] in
   188	            defer { group.leave() }
   189	            if isStopping { videoReader.cancelReading() }
   190	        }
   191	        if let opus, let output = audioOutput, let audioReader {
   192	            group.enter()
   193	            audioQueue.async { [self] in
   194	                defer { group.leave() }
   195	                pumpAudio(output, into: webm, through: opus)
   196	                // Its own reader, after its own last read (G-17).
   197	                if isStopping { audioReader.cancelReading() }
   198	            }
   199	        }
   200	        group.notify(queue: .main) { [weak self] in self?.allPumpsLeft() }
   201	    }
   202	
   203	    /// Sets the flag; both pumps see it before their next sample. Any thread, any time.
   204	    func cancel() {
   205	        lock.lock()
   206	        cancelRequested = true
   207	        lock.unlock()
   208	    }
   209	
   210	    var progress: Double {
   211	        lock.lock()
   212	        defer { lock.unlock() }
   213	        return progressValue
   214	    }
   215	
   216	    // MARK: - The audio pump
   217	
   218	    /// Reads the mix to its end, encodes it and adds each packet, holding the newest back so
   219	    /// the last one can carry the tail's DiscardPadding (CX-15 (5)), or stops at the flag
   220	    /// before a read.
   221	    ///
   222	    /// **Times are the stamps'.** Each buffer is placed at its rebased stamp
   223	    /// (`ExportAudioEnd.align`: silence for a gap, the covered head cut), so the stream the
   224	    /// encoder is fed is the timeline's sound frame for frame from the range's start, and
   225	    /// packet k's first frame is the one stamped k × 960 / 48 kHz — k × 20 ms, a whole tick of
   226	    /// WebM's 1 ms timecode scale — which is the time it is added at.
   227	    private func pumpAudio(
   228	        _ output: AVAssetReaderOutput, into webm: ReelWebM, through opus: ExportOpusEncoder
   229	    ) {
   230	        let gain = audioGain
   231	        var held: Data?
   232	        var added: Int64 = 0
   233	        let packetNs = Int64(ExportOpusEncoder.framesPerPacket) * 1_000_000_000 / 48_000
   234	        let add = { (packet: Data, padding: Int64) throws in
   235	            try webm.add(
   236	                track: ReelWebM.audio, ptsNs: added * packetNs, key: true,
   237	                discardPaddingNs: padding, data: packet)
   238	            added += 1
   239	        }
   240	        let feed = { (packets: [Data]) throws in
   241	            for packet in packets {
   242	                if let previous = held { try add(previous, 0) }
   243	                held = packet
   244	            }
   245	        }
   246	        var reads = 0
   247	        do {
   248	            while true {
   249	                guard !isStopping else { return }
   250	                reads += 1
   251	                try fault?.beforeAudioRead(reads)
   252	                guard let decoded = output.copyNextSampleBuffer() else {
   253	                    if let error = readFailure(of: audioReader) {
   254	                        stopped(with: error)
   255	                        return
   256	                    }
   257	                    break
   258	                }
   259	                let time = CMSampleBufferGetPresentationTimeStamp(decoded) - range.start
   260	                guard time.isNumeric, time >= .zero else { continue }
   261	                if gain != nil, CMSampleBufferGetNumSamples(decoded) == 0 { continue }
   262	                guard let sample = gain == nil ? decoded : gain?.apply(to: decoded) else {
   263	                    stopped(with: Exporter.ExportError.failed(
   264	                        "The loudness gain could not be applied to a sample."))
   265	                    return
   266	                }
   267	                let frame = CMTimeConvertScale(
   268	                    time, timescale: CMTimeScale(ExportAudioEnd.sampleRate),
   269	                    method: .roundHalfAwayFromZero
   270	                ).value
   271	                for placed in audioEnd.align(sample, at: Int(frame)) {
   272	                    guard let fitted = audioEnd.fit(placed) else { continue }
   273	                    try feed(try opus.encode(fitted))
   274	                }
   275	            }
   276	            for silence in audioEnd.padding() {
   277	                try feed(try opus.encode(silence))
   278	            }
   279	            var tail = (held.map { [$0] } ?? []) + (try opus.finish())
   280	            // The decoded length is packets × 960 − pre-skip; the surplus over #337's
   281	            // target is cut whole packets first, then by the last one's DiscardPadding.
   282	            var padding = (Int(added) + tail.count) * ExportOpusEncoder.framesPerPacket
   283	                - opus.preSkip - audioEnd.target
   284	            while padding >= ExportOpusEncoder.framesPerPacket, !tail.isEmpty {
   285	                tail.removeLast()
   286	                padding -= ExportOpusEncoder.framesPerPacket
   287	            }
   288	            guard padding >= 0, padding < ExportOpusEncoder.framesPerPacket else {
   289	                stopped(with: Exporter.ExportError.failed(
   290	                    "The audio could not be encoded to its exact length."))
   291	                return
   292	            }
   293	            let paddingNs = (Int64(padding) * 1_000_000_000 + 24_000) / 48_000
   294	            for (index, packet) in tail.enumerated() {
   295	                try add(packet, index == tail.count - 1 ? paddingNs : 0)
   296	            }
   297	            try webm.endTrack(ReelWebM.audio)
   298	        } catch {
   299	            stopped(with: error)
   300	        }
   301	    }
   302	
   303	    // MARK: - Finishing
   304	
   305	    private var isStopping: Bool {
   306	        lock.lock()
   307	        defer { lock.unlock() }
   308	        return cancelRequested || failure != nil
   309	    }
   310	
   311	    private func stopped(with error: any Error) {
   312	        lock.lock()
   313	        let first = failure == nil
   314	        if first { failure = error }
   315	        lock.unlock()
   316	        // The unified log (not stdout or the proofs' log), so a stop names its cause.
   317	        let which = first ? "first" : "later"
   318	        let why = error.localizedDescription
   319	        Self.log.error(
   320	            "WebM export stopped (\(which, privacy: .public)): \(why, privacy: .public)")
   321	    }
   322	
   323	    private static let log = Logger(subsystem: "com.kgalligan.FrameJob", category: "export.webm")
   324	
   325	    private func readFailure(of reader: AVAssetReader?) -> (any Error)? {
   326	        guard let reader, reader.status == .failed else { return nil }
   327	        return reader.error
   328	            ?? Exporter.ExportError.failed("The composition could not be read to the end.")
   329	    }
   330	
   331	    private func advance(to time: CMTime) {
   332	        guard totalSeconds > 0 else { return }
   333	        let fraction = CMTimeGetSeconds(time) / totalSeconds
   334	        lock.lock()
   335	        progressValue = min(max(fraction, progressValue), 1)
   336	        lock.unlock()
   337	    }
   338	
   339	    /// Main thread, once both pumps have left (each reader already cancelled by its own
   340	    /// pump on a stop): the encoder closed, then the file finished off main or dropped and
   341	    /// removed.
   342	    private func allPumpsLeft() {
   343	        lock.lock()
   344	        let error = failure
   345	        let cancelled = cancelRequested
   346	        lock.unlock()
   347	        if fault != nil {
   348	            let shared = audioReader === videoReader ? " (one reader)" : ""
   349	            ExportWebMDevFault.log(
   350	                "readers: video \(videoReader.status.rawValue), audio "
   351	                    + (audioReader.map { "\($0.status.rawValue)" } ?? "none") + shared)
   352	        }
   353	        pump.close()
   354	        if let error { return finishFailed(error) }
   355	        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
   356	        guard let webm else { return finishFailed(Exporter.ExportError.cancelled) }
   357	        videoQueue.async { [weak self] in
   358	            let closed: (any Error)?
   359	            do {
   360	                try webm.finish()
   361	                closed = nil
   362	            } catch {
   363	                closed = Exporter.ExportError.failed(
   364	                    "The WebM file could not be finished: \(error.localizedDescription)")
   365	            }
   366	            DispatchQueue.main.async { self?.fileClosed(closed) }
   367	        }
   368	    }
   369	
   370	    private func fileClosed(_ error: (any Error)?) {
   371	        lock.lock()
   372	        let cancelled = cancelRequested
   373	        lock.unlock()
   374	        if let error { return finishFailed(error) }
   375	        // A cancel while the file was being closed still means "I do not want this file".
   376	        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
   377	        lock.lock()
   378	        progressValue = 1
   379	        lock.unlock()
   380	        report(.success(destination))
   381	    }
   382	
   383	    private func finishFailed(_ error: any Error) {
   384	        discard()
   385	        report(.failure(error))
   386	    }
   387	
   388	    /// Drops the writer and removes the part-written file.
   389	    private func discard() {
   390	        webm = nil
   391	        try? FileManager.default.removeItem(at: destination)
   392	    }
   393	
   394	    /// The one exit, main thread, at most once.
   395	    private func report(_ result: Result<URL, any Error>) {
   396	        guard let completion else { return }
   397	        self.completion = nil
   398	        completion(result)
   399	    }
   400	}

