//! A test-only EBML WALK — the independent oracle for what the WebM writer
//! (`rc_webm_*`, spec §11 CX-15) puts where #216-R's reader does not look:
//! the SeekHead, Info's Duration, Chapters, Cues, the Segment's size, the
//! Cluster and block order and DiscardPadding. Written from RFC 8794 and RFC
//! 9559, never from `core/src/webm_*.rs`: it parses the whole file into a
//! tree of elements, by a list of master IDs of its own.

/// One element: its ID (marker bits included), where its header starts, where
/// its data starts, how long its data is, and its children when a master.
#[derive(Debug, Clone)]
pub struct Element {
    pub id: u32,
    pub start: usize,
    pub data: usize,
    pub size: usize,
    pub children: Vec<Element>,
}

/// The masters this walk descends into.
const MASTERS: [u32; 20] = [
    0x1A45_DFA3, // EBML
    0x1853_8067, // Segment
    0x114D_9B74, // SeekHead
    0x4DBB,      // Seek
    0x1549_A966, // Info
    0x1654_AE6B, // Tracks
    0xAE,        // TrackEntry
    0xE0,        // Video
    0x55B0,      // Colour
    0x55D0,      // MasteringMetadata
    0xE1,        // Audio
    0x1043_A770, // Chapters
    0x45B9,      // EditionEntry
    0xB6,        // ChapterAtom
    0x80,        // ChapterDisplay
    0x1F43_B675, // Cluster
    0xA0,        // BlockGroup
    0x1C53_BB6B, // Cues
    0xBB,        // CuePoint
    0xB7,        // CueTrackPositions
];

/// An element ID at `at` (1–4 bytes, the length from the first byte's
/// leading zeros), marker kept; and its length.
fn read_id(bytes: &[u8], at: usize) -> (u32, usize) {
    let first = bytes[at];
    let len = first.leading_zeros() as usize + 1;
    assert!(len <= 4, "an ID of {len} bytes at {at}");
    let id = bytes[at..at + len]
        .iter()
        .fold(0u32, |v, b| (v << 8) | u32::from(*b));
    (id, len)
}

/// A size vint at `at`, marker removed; and its length. The all-ones value
/// ("unknown") is `None`.
pub fn read_size(bytes: &[u8], at: usize) -> (Option<u64>, usize) {
    let first = bytes[at];
    let len = first.leading_zeros() as usize + 1;
    assert!(len <= 8, "a size of {len} bytes at {at}");
    let mut v = u64::from(first) & ((1u64 << (8 - len)) - 1);
    for b in &bytes[at + 1..at + len] {
        v = (v << 8) | u64::from(*b);
    }
    let unknown = v == (1u64 << (7 * len)) - 1;
    ((!unknown).then_some(v), len)
}

/// Every element from `from` to `to`, children parsed for masters. A size
/// that is unknown or runs past `to` fails the test.
pub fn walk(bytes: &[u8], from: usize, to: usize) -> Vec<Element> {
    let mut out = Vec::new();
    let mut at = from;
    while at < to {
        let (id, id_len) = read_id(bytes, at);
        let (size, size_len) = read_size(bytes, at + id_len);
        let size =
            size.unwrap_or_else(|| panic!("element {id:#x} at {at} has an unknown size")) as usize;
        let data = at + id_len + size_len;
        assert!(data + size <= to, "element {id:#x} at {at} runs past {to}");
        let children = if MASTERS.contains(&id) {
            walk(bytes, data, data + size)
        } else {
            Vec::new()
        };
        out.push(Element {
            id,
            start: at,
            data,
            size,
            children,
        });
        at = data + size;
    }
    out
}

impl Element {
    /// The first child with `id`.
    pub fn child(&self, id: u32) -> Option<&Element> {
        self.children.iter().find(|e| e.id == id)
    }

    /// Every child with `id`, in order.
    pub fn all(&self, id: u32) -> Vec<&Element> {
        self.children.iter().filter(|e| e.id == id).collect()
    }

    pub fn body<'a>(&self, bytes: &'a [u8]) -> &'a [u8] {
        &bytes[self.data..self.data + self.size]
    }

    pub fn uint(&self, bytes: &[u8]) -> u64 {
        self.body(bytes)
            .iter()
            .fold(0u64, |v, b| (v << 8) | u64::from(*b))
    }

    pub fn int(&self, bytes: &[u8]) -> i64 {
        let body = self.body(bytes);
        let negative = body.first().is_some_and(|b| b & 0x80 != 0);
        let start: i64 = if negative { -1 } else { 0 };
        body.iter().fold(start, |v, b| (v << 8) | i64::from(*b))
    }

    pub fn float(&self, bytes: &[u8]) -> f64 {
        let body = self.body(bytes);
        match body.len() {
            4 => f64::from(f32::from_be_bytes(body.try_into().expect("4 bytes"))),
            8 => f64::from_be_bytes(body.try_into().expect("8 bytes")),
            n => panic!("a float of {n} bytes"),
        }
    }

    pub fn string(&self, bytes: &[u8]) -> String {
        String::from_utf8(self.body(bytes).to_vec()).expect("a UTF-8 string")
    }
}

/// The file's top level and its Segment, whose children are the level-1
/// elements; the Segment's size must be known.
pub fn segment(bytes: &[u8]) -> (Vec<Element>, Element) {
    let top = walk(bytes, 0, bytes.len());
    let segment = top
        .iter()
        .find(|e| e.id == 0x1853_8067)
        .expect("a Segment")
        .clone();
    (top, segment)
}

/// One block as the file holds it: its track, its absolute time in ms, its
/// flags, its frame's bytes, and the DiscardPadding of its group if any.
#[derive(Debug, Clone)]
pub struct BlockRead {
    pub track: u64,
    pub ms: i64,
    pub flags: u8,
    pub frame: Vec<u8>,
    pub discard: Option<i64>,
    pub cluster_start: usize,
}

/// Every block of every Cluster, in file order.
pub fn blocks(bytes: &[u8], segment: &Element) -> Vec<BlockRead> {
    let mut out = Vec::new();
    for cluster in segment.all(0x1F43_B675) {
        let time = cluster
            .child(0xE7)
            .expect("a Cluster Timestamp")
            .uint(bytes) as i64;
        for e in &cluster.children {
            let (block, discard) = match e.id {
                0xA3 => (e, None),
                0xA0 => (
                    e.child(0xA1).expect("a BlockGroup's Block"),
                    e.child(0x75A2).map(|d| d.int(bytes)),
                ),
                _ => continue,
            };
            let body = block.body(bytes);
            let (track, len) = read_size(body, 0);
            let rel = i16::from_be_bytes([body[len], body[len + 1]]);
            out.push(BlockRead {
                track: track.expect("a track number"),
                ms: time + i64::from(rel),
                flags: body[len + 2],
                frame: body[len + 3..].to_vec(),
                discard,
                cluster_start: cluster.start,
            });
        }
    }
    out
}
//! Black-box tests for the WebM writer's VP9 track — spec §11 CX-16
//! (codec-export C4) — through `rc_webm_*` as `ExportWebMWriter` drives it for
//! `vp9_webm`: a Profile 0 SDR file and a Profile 2 PQ file, each read back
//! through #216-R's reader (`V_VP9` as `vp09`, the `vpcC` it builds from the
//! first keyframe and the Colour, the key flags) and through
//! `common/ebml_read.rs`'s walk (no CodecPrivate, the Colour's codes,
//! BitsPerChannel and the mastering metadata, the blocks' key flags).

mod common;

use serde_json::json;

use common::ebml_read::{blocks, segment};
use common::webm::*;
use framejob_core::container::{Container, VIDEO};

/// What the reader's `vpcC` is for a profile, depth and CICP: version 1,
/// level 0, 4:2:0 co-sited, studio range, no codec initialisation data.
fn vpcc(profile: u8, depth: u8, cicp: [u8; 3]) -> String {
    hex(&[
        1,
        0,
        0,
        0,
        profile,
        0,
        (depth << 4) | (1 << 1),
        cicp[0],
        cicp[1],
        cicp[2],
        0,
        0,
    ])
}

#[test]
fn a_profile_0_sdr_file_reads_back_as_vp09() {
    let path = temp_path("vp9-sdr");
    write_vp9(&path, true);
    let c = Container::open(&path).expect("the reader opens it");
    let d = c.describe();
    let v = &d["video"];
    assert_eq!(v["codec_id"], json!("V_VP9"));
    assert_eq!(v["fourcc"], json!("vp09"));
    assert_eq!(v["atom"], json!("vpcC"));
    assert_eq!(v["vp9_profile"], json!(0));
    assert_eq!(v["atom_hex"], json!(vpcc(0, 8, [1, 1, 1])));
    assert_eq!(
        (
            v["matrix"].clone(),
            v["transfer"].clone(),
            v["primaries"].clone()
        ),
        (json!(1), json!(1), json!(1))
    );
    assert!(v["mdcv_hex"].is_null() && v["clli_hex"].is_null());
    assert_eq!(v["stream_matrix"], json!(1), "CS_BT_709");
    assert_eq!(v["samples"], json!(60));
    assert_eq!(d["audio"]["samples"], json!(100));
}

#[test]
fn a_profile_2_pq_file_reads_back_as_vp09_with_its_hdr10() {
    let path = temp_path("vp9-pq");
    write_vp9(&path, false);
    let c = Container::open(&path).expect("the reader opens it");
    let d = c.describe();
    let v = &d["video"];
    assert_eq!(v["codec_id"], json!("V_VP9"));
    assert_eq!(v["fourcc"], json!("vp09"));
    assert_eq!(v["vp9_profile"], json!(2));
    assert_eq!(v["atom_hex"], json!(vpcc(2, 10, [9, 16, 9])));
    assert_eq!(v["stream_matrix"], json!(9), "CS_BT_2020");
    assert_eq!(v["mdcv_hex"], json!(MDCV));
    assert_eq!(v["clli_hex"], json!(CLLI));
}

#[test]
fn the_walk_finds_no_codec_private_and_the_colour() {
    for (sdr, cicp, bits) in [(true, [1, 1, 1], 8), (false, [9, 16, 9], 10)] {
        let path = temp_path("vp9-walk");
        write_vp9(&path, sdr);
        let b = std::fs::read(&path).expect("read");
        let (_, seg) = segment(&b);
        let entries = find(&seg, 0x1654_AE6B).all(0xAE);
        let v = entries[0];
        assert_eq!(find(v, 0x86).string(&b), "V_VP9");
        assert!(v.child(0x63A2).is_none(), "a V_VP9 CodecPrivate");
        assert!(entries[1].child(0x63A2).is_some(), "OpusHead stays");
        let colour = find(find(v, 0xE0), 0x55B0);
        assert_eq!(find(colour, 0x55B1).uint(&b), cicp[0]);
        assert_eq!(find(colour, 0x55BA).uint(&b), cicp[1]);
        assert_eq!(find(colour, 0x55BB).uint(&b), cicp[2]);
        assert_eq!(find(colour, 0x55B9).uint(&b), 1);
        assert_eq!(find(colour, 0x55B2).uint(&b), bits);
        if sdr {
            assert!(colour.child(0x55D0).is_none() && colour.child(0x55BC).is_none());
        } else {
            assert_eq!(find(colour, 0x55BC).uint(&b), 1000);
            assert_eq!(find(colour, 0x55BD).uint(&b), 0);
            let m = find(colour, 0x55D0);
            assert_eq!(find(m, 0x55D9).float(&b), 1000.0);
            assert_eq!(find(m, 0x55DA).float(&b), 0.005);
        }
    }
}

#[test]
fn key_flags_are_the_packets_in_the_walk_and_the_reader() {
    for sdr in [true, false] {
        let path = temp_path("vp9-keys");
        write_vp9(&path, sdr);
        let b = std::fs::read(&path).expect("read");
        let (_, seg) = segment(&b);
        let video: Vec<_> = blocks(&b, &seg)
            .into_iter()
            .filter(|r| r.track == 1)
            .collect();
        assert_eq!(video.len(), 60);
        let profile = if sdr { 0 } else { 2 };
        for (k, r) in video.iter().enumerate() {
            let key = k % 30 == 0;
            assert_eq!(r.flags & 0x80 != 0, key, "block {k}");
            assert_eq!(r.frame, vp9_frame(k, profile, key), "block {k}");
        }
        let c = Container::open(&path).expect("open");
        for k in 0..60u64 {
            let s = c.sample(VIDEO, k).expect("a sample");
            assert_eq!(s.sync, k % 30 == 0, "sample {k}");
        }
    }
}

#[test]
fn the_keyframe_colour_space_is_published_as_the_stream_matrix() {
    // Spec §11 CX-16 (10): CS_BT_709 → 1, CS_BT_601 and CS_SMPTE_170 → 6, CS_BT_2020 → 9,
    // CS_UNKNOWN and every other space (240M, reserved, RGB) → null.
    for (space, want) in [
        (0u8, json!(null)),
        (1, json!(6)),
        (2, json!(1)),
        (3, json!(6)),
        (4, json!(null)),
        (5, json!(9)),
        (6, json!(null)),
    ] {
        let path = temp_path("vp9-space");
        let mut video = vp9_layout([30, 1], true);
        video.as_object_mut().unwrap().remove("colour");
        video["colour"] = json!({"matrix": 2, "range": 1, "transfer": 2, "primaries": 2,
                                 "bits_per_channel": 8});
        let layout = json!({"duration_ns": SECOND, "video": video});
        let w = Webm::open(&path, &layout).expect("open");
        for k in 0..30 {
            w.add(
                V,
                frame_ns(k, 30, 1),
                k == 0,
                0,
                &vp9_frame_in(k, 0, k == 0, space),
            )
            .expect("add");
        }
        w.finish().expect("finish");
        let c = Container::open(&path).expect("open");
        assert_eq!(
            c.describe()["video"]["stream_matrix"],
            want,
            "space {space}"
        );
    }
}

