import AVFoundation

/// The video pump of a row a bundled encoder writes (`settings.writer`, spec §11 CX-12,
/// CX-15, CX-16): the composed frames converted to I010 (I420 for `vp9_webm`'s SDR picture) on
/// the export's video queue and encoded on a serial encode queue of its own — by SVT-AV1 for
/// `svt_av1`, by libvpx's VP9 for `libvpx` (`ExportVideoEncoder`) — whose packets go to an
/// `ExportPacketSink`: the `av1` row's passthrough `AVAssetWriterInput` as `av01` samples, or
/// the WebM rows' core writer.
///
/// **Two queues, one owner each.** The video queue reads, converts and hands each frame on,
/// bounded to three in flight (`slots`) so a slow encoder holds the read back; the encode
/// queue owns the encoder and the sink — every `send`, every packet, every append, the
/// flush and the sink's `finish`. Progress is counted by frames SUBMITTED (the encoder's lag
/// is under a second); a cancel is the writer's flag, read before each read, each send and
/// each wait in the sink.
///
/// **The finish** runs once on the encode queue, after every frame queued before it: at the
/// end of a clean read, the end of stream and a drain to the last packet; on a stop (a
/// cancel, a failed read, another pump's failure), the end of stream and a drain that
/// discards; after an encoder error, neither. Every exit finishes the sink and leaves the
/// group exactly once. The encoder itself is torn down by `close()`, after the writer's
/// pumps have all left, as the reader is (G-17).
final class ExportEncodePump {
    /// The settings' `writer` values this pump serves: SVT-AV1 (the AV1 rows) and libvpx
    /// (`vp9_webm`, CX-16).
    static let av1Writer = "svt_av1"
    static let vp9Writer = "libvpx"

    /// The `av01` description the MP4 sink's samples carry; nil on libvpx, which has no MP4
    /// row (CX-1).
    let formatDescription: CMVideoFormatDescription?
    /// The WebM layout's video track (`ExportWebMLayout`): `V_AV1` with the `av1C` record and
    /// the sequence header's colour at 10 bits, or `V_VP9` with no CodecPrivate, the picture's
    /// CICP and its depth (CX-16 (4), (5)).
    let webmCodec: ExportWebMLayout.VideoCodec
    /// The picture the frames are.
    let picture: ExportAV1Picture

    private var encoder: (any ExportVideoEncoder)?
    /// The encoder's name, for a sentence after it is torn down.
    private let encoderName: String
    private let converter: ExportI010Converter
    private let encodeQueue = DispatchQueue(
        label: "com.kgalligan.framejob.export.encode", qos: .userInitiated)
    private let range: CMTimeRange
    private let frameDuration: CMTime
    private let slots = DispatchSemaphore(value: 3)

    // The encode queue's own state.
    private var times: [Int64: CMTime] = [:]
    private var lastTime = CMTime.negativeInfinity
    private var encoderFailed = false
    private var finished = false

    init(settings: ExportSettings, canvas: CGSize, range: CMTimeRange) throws {
        let frame = ExportWriter.encodedSize(settings)
        let rate = settings.videoBitrate.map { max(1, $0) }
            ?? ExportWriter.defaultVideoBitrate(settings, bitsPerPixel: 0.07)
        let picture = ExportAV1Picture(color: settings.color)
        let encoder: any ExportVideoEncoder
        let bitDepth: Int
        if settings.writer == Self.vp9Writer {
            bitDepth = VP9Encoder.bitDepth(for: picture)
            encoder = try VP9Encoder(
                width: frame.width, height: frame.height, fps: settings.fps,
                bitsPerSecond: rate, picture: picture)
            let cicp = picture.cicp
            webmCodec = ExportWebMLayout.VideoCodec(
                codecId: "V_VP9", codecPrivate: nil, primaries: cicp.primaries,
                transfer: cicp.transfer, matrix: cicp.matrix, bitsPerChannel: bitDepth)
            formatDescription = nil
        } else {
            bitDepth = 10
            let svt = try SVTAV1Encoder(
                width: frame.width, height: frame.height, fps: settings.fps,
                bitsPerSecond: rate, speed: settings.encoderSpeed ?? .balanced, picture: picture)
            let config: ReelAV1.Config
            do {
                config = try ReelAV1.config(sequenceHeader: svt.sequenceHeader)
            } catch {
                throw Exporter.ExportError.failed(
                    "SVT-AV1's sequence header could not be read: \(error.localizedDescription)")
            }
            encoder = svt
            webmCodec = ExportWebMLayout.VideoCodec(
                codecId: "V_AV1", codecPrivate: config.record, primaries: config.color.primaries,
                transfer: config.color.transfer, matrix: config.color.matrix, bitsPerChannel: 10)
            formatDescription = try ExportAV1Track.formatDescription(
                width: frame.width, height: frame.height, config: config, picture: picture)
        }
        converter = try ExportI010Converter(
            width: frame.width, height: frame.height, canvas: canvas,
            fills: ExportWriter.fillsTheBox(settings, canvas: canvas), picture: picture,
            bitDepth: bitDepth, pool: 3)
        self.encoder = encoder
        encoderName = encoder.name
        self.picture = picture
        self.range = range
        self.frameDuration = CompositionBuilder.frameDuration(settings.fps)
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ExportEncodePump does not support NSCoder")
    }

    /// Reads `output` to its end on `queue` and encodes it into `sink`; `group` is left once
    /// the sink is finished. `readFailure` answers the reader's error when the read failed;
    /// `fail` records the first failure; `advance` is each submitted frame's file time.
    func run(
        sink: any ExportPacketSink, output: AVAssetReaderOutput, on queue: DispatchQueue,
        group: DispatchGroup, isStopping: @escaping () -> Bool,
        readFailure: @escaping () -> (any Error)?, fail: @escaping (any Error) -> Void,
        advance: @escaping (CMTime) -> Void
    ) {
        group.enter()
        let finish: (Bool) -> Void = { [self] clean in
            encodeQueue.async {
                self.finish(
                    clean: clean, sink: sink, group: group, isStopping: isStopping, fail: fail)
            }
        }
        queue.async { [self] in
            var index: Int64 = 0
            while true {
                guard !isStopping() else { return finish(false) }
                guard let sample = output.copyNextSampleBuffer() else {
                    // Dry: the range is read, or the read failed — never a branded, done
                    // file after a failed read.
                    if let error = readFailure() {
                        fail(error)
                        return finish(false)
                    }
                    return finish(true)
                }
                let time = CMSampleBufferGetPresentationTimeStamp(sample) - range.start
                guard time.isNumeric, time >= .zero else { continue }
                slots.wait()
                guard let pixels = CMSampleBufferGetImageBuffer(sample),
                    let frame = converter.convert(pixels)
                else {
                    slots.signal()
                    fail(Exporter.ExportError.failed(
                        "A frame could not be prepared for the encoder."))
                    return finish(false)
                }
                let at = index
                index += 1
                encodeQueue.async {
                    self.encode(
                        frame, index: at, time: time, sink: sink, isStopping: isStopping,
                        fail: fail)
                }
                advance(time)
            }
        }
    }

    /// The encoder's teardown, on the encode queue, once every input is finished.
    func close() {
        encodeQueue.async { [self] in encoder = nil }
    }

    // MARK: - The encode queue

    private func encode(
        _ frame: I010Frame, index: Int64, time: CMTime, sink: any ExportPacketSink,
        isStopping: () -> Bool, fail: (any Error) -> Void
    ) {
        defer {
            converter.recycle(frame)
            slots.signal()
        }
        guard !finished, !encoderFailed, !isStopping(), let encoder else { return }
        do {
            try encoder.send(frame, index: index)
            times[index] = time
            while let packet = try encoder.nextPacket(wait: false) {
                guard write(packet, sink: sink, isStopping: isStopping, fail: fail) else {
                    return
                }
            }
        } catch {
            encoderFailed = true
            fail(error)
        }
    }

    /// One packet into the file: false once the export cannot go on.
    private func write(
        _ packet: ExportEncodedPacket, sink: any ExportPacketSink, isStopping: () -> Bool,
        fail: (any Error) -> Void
    ) -> Bool {
        guard !packet.data.isEmpty else { return true }
        let data: Data
        do {
            data = try encoder?.containerBytes(packet.data) ?? packet.data
        } catch {
            fail(error)
            return false
        }
        guard let time = times.removeValue(forKey: packet.pts), time > lastTime else {
            fail(Exporter.ExportError.failed("\(encoderName) wrote a frame out of order."))
            return false
        }
        lastTime = time
        if let error = sink.append(
            data, at: time, duration: frameDuration, key: packet.isKey, isStopping: isStopping)
        {
            if !(error is ExportPacketSinkStopped) { fail(error) }
            return false
        }
        return true
    }

    /// The one exit: the end of stream and the drain as `clean` and the encoder allow, then
    /// the sink finished and the group left, exactly once.
    private func finish(
        clean: Bool, sink: any ExportPacketSink, group: DispatchGroup, isStopping: () -> Bool,
        fail: (any Error) -> Void
    ) {
        guard !finished else { return }
        finished = true
        defer {
            sink.finish()
            group.leave()
        }
        guard !encoderFailed, let encoder else { return }
        do {
            try encoder.sendEndOfStream()
            var writing = clean && !isStopping()
            while let packet = try encoder.nextPacket(wait: true) {
                if writing {
                    writing = write(packet, sink: sink, isStopping: isStopping, fail: fail)
                }
                if packet.isLast { break }
            }
        } catch {
            encoderFailed = true
            if clean { fail(error) }
        }
    }
}
import Foundation

/// One packet as a bundled encoder answered it (spec §11 CX-12, CX-15 (3), CX-16 (6)): its
/// bytes as the encoder wrote them, the `pts` the picture was sent with (its frame index),
/// whether it is the last, and whether it is a key — a KEY_FRAME for SVT-AV1, libvpx's
/// `VPX_FRAME_IS_KEY` for VP9 — which the WebM writer flags.
struct ExportEncodedPacket {
    let data: Data
    let pts: Int64
    let isLast: Bool
    let isKey: Bool
}

/// What `ExportEncodePump` asks of a bundled encoder (spec §11 CX-12, CX-16): SVT-AV1 for the
/// AV1 rows (`SVTAV1Encoder`), libvpx's VP9 for `vp9_webm` (`VP9Encoder`). Every call after
/// `init` is made on the pump's encode queue alone.
protocol ExportVideoEncoder: AnyObject {
    /// The library's name in a sentence ("SVT-AV1", "libvpx").
    var name: String { get }
    /// Sends one picture, `index` its pts; the encoder copies the planes, so `frame` may be
    /// reused once this returns.
    func send(_ frame: I010Frame, index: Int64) throws
    /// No picture follows, so `nextPacket(wait: true)` drains to the last packet.
    func sendEndOfStream() throws
    /// The next packet: nil when none is ready (`wait` false). `wait` true is asked only after
    /// `sendEndOfStream` and answers nil once the encoder is drained.
    func nextPacket(wait: Bool) throws -> ExportEncodedPacket?
    /// A packet's bytes as the container takes them: SVT-AV1's with their temporal delimiters
    /// stripped (CX-12 (4)), VP9's as they are. Throws when the bytes cannot be read.
    func containerBytes(_ data: Data) throws -> Data
}

/// A bundled encoder's rate table (spec §11 CX-13 (3), CX-16 (7)): a constant quality — a CRF
/// or a CQ level — as a function of the cap's bits per pixel per frame.
enum ExportRateTable {
    /// The value at `bitsPerPixel`: linear between `points` (ascending in bits per pixel),
    /// rounded down (a lower value is the better picture), and the end point's value beyond
    /// either end. An empty table is a programming error, never a value: 0 would ask for the
    /// largest file the encoder can make.
    static func value(
        at bitsPerPixel: Double, points: [(bitsPerPixel: Double, value: Double)]
    ) -> UInt32 {
        guard let first = points.first, let last = points.last else {
            preconditionFailure("ExportRateTable.value: an empty rate table")
        }
        if !(bitsPerPixel > first.bitsPerPixel) { return UInt32(first.value) }
        if bitsPerPixel >= last.bitsPerPixel { return UInt32(last.value) }
        for (low, high) in zip(points, points.dropFirst()) where bitsPerPixel < high.bitsPerPixel {
            let share = (bitsPerPixel - low.bitsPerPixel) / (high.bitsPerPixel - low.bitsPerPixel)
            return UInt32((low.value + share * (high.value - low.value)).rounded(.down))
        }
        return UInt32(last.value)
    }
}

